/**
 * Decks Marketplace client contract (server: apps/web, routes under
 * /api/decks/packs). Catalogue JSON is generated by the Skin SDK
 * (`mixaipack catalog`) into apps/web/src/lib/decks-packs/catalog.json.
 *
 *   GET  {origin}/api/decks/packs                -> MarketCatalog (public, CORS *)
 *   GET  {origin}/api/decks/packs/{id}/download  -> application/octet-stream (.mixaipack)
 *        free packs: no auth; pro packs: `Authorization: Bearer <device token>` of a
 *        device whose user has the `decks_pro` entitlement, else 402 { error: "pro_required" }.
 *
 * The app ALWAYS re-verifies the downloaded bytes in Rust (signature, limits,
 * sha256 must equal the catalogue entry) before trying or installing.
 */

export const MARKET_ORIGIN = "https://mixai.ro";

export interface MarketPack {
    id: string;
    name: string;
    version: string;
    kind: "skin" | "layout" | "bundle" | "controller";
    author: string;
    description: string;
    pro: boolean;
    trust: "official" | "verified" | "community" | "unsigned";
    /** Bytes of the archive. */
    size: number;
    /** SHA-256 hex of the archive (checked after download). */
    sha256: string;
    /** Absolute or origin-relative URL of a preview image (png/webp/jpg). */
    previewUrl: string | null;
    tags: string[];
    /** ISO date of this version. */
    updatedAt: string;
}

export interface MarketCatalog {
    v: 1;
    generatedAt: string;
    packs: MarketPack[];
}

export function isMarketCatalog(x: unknown): x is MarketCatalog {
    if (!x || typeof x !== "object") return false;
    const c = x as Partial<MarketCatalog>;
    return c.v === 1 && Array.isArray(c.packs) && c.packs.every((p) => p && typeof p.id === "string" && typeof p.sha256 === "string" && typeof p.pro === "boolean");
}

export function absoluteUrl(url: string | null, origin = MARKET_ORIGIN): string | null {
    if (!url) return null;
    if (/^https:\/\//.test(url)) return url;
    if (url.startsWith("/")) return origin + url;
    return null;
}

export async function fetchCatalog(origin = MARKET_ORIGIN, signal?: AbortSignal): Promise<MarketCatalog> {
    const res = await fetch(`${origin}/api/decks/packs`, { signal, headers: { accept: "application/json" } });
    if (!res.ok) throw new Error(`catalog ${res.status}`);
    const data: unknown = await res.json();
    if (!isMarketCatalog(data)) throw new Error("catalog: unexpected shape");
    return data;
}

export async function downloadPack(p: MarketPack, deviceToken: string | null, origin = MARKET_ORIGIN, signal?: AbortSignal): Promise<Uint8Array> {
    const headers: Record<string, string> = {};
    if (p.pro && deviceToken) headers.authorization = `Bearer ${deviceToken}`;
    const res = await fetch(`${origin}/api/decks/packs/${encodeURIComponent(p.id)}/download`, { signal, headers });
    if (res.status === 401 || res.status === 402) throw new Error("pro_required");
    if (!res.ok) throw new Error(`download ${res.status}`);
    const buf = new Uint8Array(await res.arrayBuffer());
    if (buf.byteLength > 25 * 1024 * 1024) throw new Error("too_large");
    const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", buf));
    const hex = [...digest].map((b) => b.toString(16).padStart(2, "0")).join("");
    if (hex !== p.sha256.toLowerCase()) throw new Error("sha256_mismatch");
    return buf;
}
